    /// The names Grok Bot stores, to the outlines above. A blob is a plain ball.
    static func named(_ name: String?) -> Shape? {
        switch name {
        case nil, "blob": return nil
        case "star": return all["star6"]
        default: return all[name!]
        }
    }

    /// The shape Grok Bot gives a bot that has none set: a hash of its id picks one of eight.
    static func defaultName(for id: String) -> String {
        let pool = ["blob", "pebble", "squircle", "tablet", "wedge", "hex", "cloud", "teardrop"]
        var t: UInt32 = 2_166_136_261
        for unit in id.utf16 { t = (t ^ UInt32(unit)) &* 16_777_619 }
        t = (t ^ (t >> 16)) &* 73_244_475
        t = (t ^ (t >> 13)) &* 3_266_489_909
        t = t ^ (t >> 16)
        return pool[Int(t % UInt32(pool.count))]
    }

    private static func points(_ v: [Double]) -> [CGPoint] {
        stride(from: 0, to: v.count - 1, by: 2).map { CGPoint(x: v[$0], y: v[$0 + 1]) }
    }
}
